SELECT jsonb_build_object('owner_count',count(*) FILTER (WHERE t.tgname='owner_commit'),'physical_count',count(*) FILTER (WHERE t.tgname='physical_guard'),'all_enabled',coalesce(bool_and(t.tgenabled='O'),false)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname::text||'.'||c.relname::text=ANY(ARRAY['app.users','app.user_security_profiles','app.age_gate_attempts','app.age_gate_blocks','app.access_audit_logs','app.user_roles','app.audit_events','app.auth_provider_accounts']::text[]) AND t.tgname IN ('owner_commit','physical_guard') AND NOT t.tgisinternal;
